(async () => {
  const browser = await puppeteer.launch({
    headless: 'shell',
    args: ['--no-sandbox','--disable-setuid-sandbox','--disable-dev-shm-usage']
  });
  // Replace scrub:true with scrub:1 on a copy of the page to test lag determinism
  let html = fs.readFileSync('scroll.html','utf8').replaceAll('scrub:true','scrub:1');
  fs.writeFileSync('scroll-lag.html', html);
  const page = await browser.newPage();
  await page.setViewport({width:540, height:720});
  await page.goto('file://' + path.resolve('scroll-lag.html'), {waitUntil:'networkidle0'});
  await page.waitForFunction('window.sampleAt && window.ScrollTrigger');
  await page.evaluate(() => ScrollTrigger.refresh());

  const samplePoints = [0, .12, .25, .37, .5, .62, .75, .87, 1];
  const out = [];
  for (const p of samplePoints) {
    const s = await page.evaluate(p => window.sampleAt(p), p);
    out.push(s);
    await page.screenshot({path: `gs-lag-${Math.round(p*100)}.png`});
  }
  fs.writeFileSync('gs-lag-samples.json', JSON.stringify(out, null, 2));
  console.log(JSON.stringify(out.map(s=>({p:s.p, y:s.scrollY, boxX:s.boxX.match(/matrix\(([^)]+)\)/)?.[1], cap0:s.cap0, cap5:s.cap5})), null, 2));
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

