import { createCaptureSession, initializeSession, getCompositionDuration, captureFrame, closeCaptureSession } from '@hyperframes/engine';
import { spawn } from 'child_process';
import http from 'http';
import fs from 'fs';
import path from 'path';

const root = process.cwd();
const server = http.createServer((req,res)=>{
  let p = path.join(root, req.url === '/' ? 'index.html' : decodeURIComponent(req.url.split('?')[0]));
  fs.readFile(p, (e,d)=>{
    if(e){res.writeHead(404);res.end();return;}
    const ext=path.extname(p);
    res.writeHead(200,{'content-type': ext==='.html'?'text/html': ext==='.js'?'text/javascript':'application/octet-stream'});
    res.end(d);
  });
});
await new Promise(r=>server.listen(8917, r));
const serverUrl = 'http://127.0.0.1:8917/';

const fps = { num: 30, den: 1 };
fs.mkdirSync('./frames',{recursive:true});
const session = await createCaptureSession(serverUrl, './frames', { width:540, height:720, fps, format:'jpeg' });
await initializeSession(session);
const duration = await getCompositionDuration(session);
console.log('composition duration:', duration);
const totalFrames = Math.ceil(duration * 30);
console.log('total frames:', totalFrames);

// capture every 15th frame (0,15,...,149) plus the last
const wanted = new Set();
for(let i=0;i<totalFrames;i+=10) wanted.add(i);
wanted.add(totalFrames-1);
for (let frame = 0; frame < totalFrames; frame++) {
  const time = frame / 30;
  await captureFrame(session, frame, time);
  if (frame % 25 === 0) process.stdout.write(`f${frame} `);
}
console.log('\ncaptured', totalFrames, 'frames');
await closeCaptureSession(session);

// encode mp4
await new Promise((res, rej)=>{
  const ff = spawn('ffmpeg', ['-y','-framerate','30','-i','frames/frame-%05d.jpeg','-c:v','libx264','-pix_fmt','yuv420p','-crf','20','scroll-video.mp4']);
  ff.stderr.on('data',()=>{});
  ff.on('close', c=> c===0?res():rej(new Error('ffmpeg '+c)));
});
console.log('mp4 written');
server.close();
process.exit(0);

