import os, subprocess

os.chdir('/home/codespace/.hermes/cache/scratch/hf-scroll-poc')

# Direct CDP experiment: fixed element + scrolled document + Page.captureScreenshot with clip
code = r'''
import puppeteer from 'puppeteer';
const b = await puppeteer.launch({headless:'shell', args:['--no-sandbox','--disable-dev-shm-usage']});
const pg = await b.newPage();
await pg.setViewport({width:540, height:720});
await pg.setContent(`<div style="position:fixed;inset:0;background:#222">
  <div style="position:absolute;left:200px;top:300px;width:90px;height:90px;background:#58a6ff;border-radius:12px"></div>
</div><div style="height:5000px"></div>`);
await new Promise(r=>setTimeout(r,300));
await pg.evaluate(() => window.scrollTo(0, 2000));
await new Promise(r=>setTimeout(r,300));
const client = await pg.createCDPSession();
const res = await client.send('Page.captureScreenshot', {format:'jpeg', quality:80, fromSurface:true, captureBeyondViewport:false, clip:{x:0,y:0,width:540,height:720,scale:1}});
import fs from 'fs';
fs.writeFileSync('cdp-scroll-clip.jpg', Buffer.from(res.data, 'base64'));
// Also puppeteer's plain screenshot for comparison
await pg.screenshot({path:'pptr-scroll-full.png'});
console.log('scrollY =', await pg.evaluate(() => window.scrollY));
await b.close();
'''
open('cdp-test.mjs','w').write(code)
r = subprocess.run(['node','cdp-test.mjs'], capture_output=True, text=True, timeout=120)
print(r.stdout, r.stderr[-200:] if r.returncode else 'clean')

from PIL import Image
from collections import Counter
im = Image.open('cdp-scroll-clip.jpg').convert('RGB')
c = Counter()
px = im.load()
blue=0
for y in range(0,720,8):
    for x in range(0,540,8):
        p = px[x,y]
        if p[2]>170 and p[0]<150: blue+=1
        c[p]+=1
print('CDP clip capture dominant:', c.most_common(2), 'blue px:', blue)
im2 = Image.open('pptr-scroll-full.png').convert('RGB')
px2 = im2.load(); blue2=0
for y in range(0,720,8):
    for x in range(0,540,8):
        p = px2[x,y]
        if p[2]>170 and p[0]<150: blue2+=1
print('puppeteer screenshot blue px:', blue2)

