import os, subprocess, glob
os.chdir('/home/codespace/.hermes/cache/scratch/hf-cli-test')
mp4 = glob.glob('renders/*.mp4')[0]
print('rendered:', mp4)

from PIL import Image
def blue_x_left(path, target=(88,166,255), tol=30):
    im = Image.open(path).convert('RGB'); w,h=im.size; px=im.load()
    for y in range(0,h,6):
        run_start=None
        for x in range(w):
            p=px[x,y]
            if all(abs(p[i]-target[i])<=tol for i in range(3)):
                if run_start is None: run_start=x
            else:
                if run_start is not None:
                    if x-run_start>=60: return run_start
                    run_start=None
        if run_start is not None and w-run_start>=60: return run_start
    return None

for n in [0, 15, 37, 74, 90, 112, 135, 149]:
    out = f'cli-{n:03d}.png'
    subprocess.run(['ffmpeg','-y','-v','error','-i',mp4,'-vf',f'select=eq(n\\,{n})','-vframes','1',out],check=True)
    print(f"  f{n:3} (t={n/30:5.2f}s): blue box left edge = {blue_x_left(out)}")
